def binary_search(arr, target):
    left = 0
    right = len(arr) - 1  # Fixed: now includes last element
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

if __name__ == "__main__":
    arr = [1, 3, 5, 7, 9, 11, 13]
    print(binary_search(arr, 13))  # Should return 6
    print(binary_search(arr, 1))   # Should return 0
    print(binary_search(arr, 7))   # Should return 3
EOF

